@media (max-width: 760px) {
  .router-overview-framework {
    min-height: 0;
    padding: 4px;
    font-size: 10px;
  }

  .ro-topbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    margin-bottom: 5px;
  }

  .ro-topbar-cell {
    min-height: 84px;
    padding: 7px 6px 6px;
  }

  .ro-topbar-cell span {
    font-size: 9px;
    line-height: 1.05;
    white-space: normal;
    min-height: 2.1em;
  }

  .ro-topbar-cell b {
    font-size: 11px;
    line-height: 1.05;
    white-space: normal;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  .ro-topbar-cell em {
    font-size: 9px;
    line-height: 1.1;
    white-space: normal;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  .ro-mobile-ledger {
    display: grid;
    gap: 0;
    border: 1px solid var(--ro-border);
    background: var(--ro-border);
    margin-bottom: 3px;
  }

  .ro-mobile-ledger > .ro-mobile-device-line {
    display: none;
  }

  .ro-mobile-row,
  .ro-mobile-device-line,
  .ro-mobile-entry {
    min-width: 0;
    background: var(--ro-surface);
    padding: 3px 4px;
  }

  .ro-mobile-row {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) minmax(84px, .96fr);
    gap: 4px;
    align-items: start;
    border-left: 2px solid transparent;
    min-height: 56px;
  }

  .ro-mobile-row.is-primary {
    border-left-color: var(--ro-danger);
  }

  .ro-mobile-row b,
  .ro-mobile-device-line b {
    overflow: visible;
    color: var(--ro-text);
    font-size: 10px;
    font-weight: 800;
    white-space: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
  }

  .ro-mobile-row em,
  .ro-mobile-device-line em {
    color: var(--ro-muted);
    font-size: 8px;
    font-style: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
  }

  .ro-mobile-device-line {
    display: grid;
    grid-template-columns: 42px minmax(0, .72fr) minmax(0, 1fr);
    gap: 4px;
  }

  .ro-mobile-entry {
    color: var(--ro-blue);
    font-size: 9px;
    font-weight: 700;
  }

  .ro-desktop-grid {
    display: none;
  }

  .ro-mobile-detail {
    display: block;
  }

  .ro-module {
    border-radius: 0;
  }

  .ro-module-head {
    min-height: 20px;
    padding: 2px 4px;
  }

  .ro-module-head b {
    font-size: 10px;
  }

  .ro-module-head span {
    display: none;
  }

  .ro-ledger-table th,
  .ro-ledger-table td,
  .ro-ledger-head-cell,
  .ro-ledger-cell {
    padding: 2px 4px;
  }

  .ro-ledger-table th,
  .ro-ledger-head-cell {
    height: 18px;
    font-size: 8px;
    white-space: normal;
    line-height: 1.05;
  }

  .ro-ledger-table td,
  .ro-ledger-cell {
    height: 20px;
    font-size: 9px;
    line-height: 1.12;
    word-break: break-word;
  }

  .ro-judgement-chart {
    padding: 3px 4px;
    gap: 2px;
  }

  .ro-judgement-row {
    grid-template-columns: 52px minmax(0, 1fr);
    gap: 3px;
    min-height: 16px;
  }

  .ro-chart-readout {
    grid-column: 1 / -1;
    font-size: 7px;
    white-space: normal;
    line-height: 1.05;
  }

  .ro-chart-label {
    font-size: 8px;
  }

  .ro-chart-track {
    height: 3px;
  }

  .ro-chain-timeline,
  .ro-visibility-matrix {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 3px 4px;
    gap: 2px;
  }

  .ro-chain-node,
  .ro-visibility-cell {
    min-height: 28px;
    padding: 2px 3px;
  }

  .ro-chain-node span,
  .ro-visibility-cell span {
    font-size: 7px;
    overflow-wrap: anywhere;
  }

  .ro-chain-node b,
  .ro-visibility-cell b {
    font-size: 8px;
    overflow-wrap: anywhere;
  }

  .ro-chain-node em,
  .ro-visibility-cell em {
    overflow-wrap: anywhere;
  }

  .ro-mobile-detail-table {
    overflow-x: clip;
  }

  .ro-mobile-ledger {
    overflow-x: clip;
  }

  .ro-mobile-first-screen {
    overflow-x: clip;
  }

  .ro-ledger-table tr[title="\5360\4f4d\5206\9694"] td,
  .ro-ledger-row[title="\5360\4f4d\5206\9694"] .ro-ledger-cell {
    height: 4px;
    padding-top: 0;
    padding-bottom: 0;
  }

  .ro-mobile-device-line,
  .ro-mobile-entry {
    display: none;
  }
}

